package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0 // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var LoanRecData LoanRec
var loanFile *os.File
var loanScanner *bufio.Scanner

func INPUT_DONE() bool {
	return WsEofFlag == "Y"
}

func pow10int64(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func fitDecimal(v decimal.Decimal, intDigits int, fracDigits int) decimal.Decimal {
	t := v.Truncate(int32(fracDigits))
	scaled := t.Shift(int32(fracDigits))
	modulus := decimal.New(1, int32(intDigits+fracDigits))
	m := scaled.Mod(modulus)
	return m.Shift(int32(-fracDigits))
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic string
	var fracDigits int
	if dotIdx == -1 {
		intPic = pic
		fracDigits = 0
	} else {
		intPic = pic[:dotIdx]
		fracDigits = len(pic) - dotIdx - 1
	}
	intPlaceCount := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == 'z' || c == '9' {
			intPlaceCount++
		}
	}
	trunc := val.Truncate(int32(fracDigits))
	absVal := trunc
	if trunc.IsNegative() {
		absVal = trunc.Abs()
	}
	scaled := absVal.Shift(int32(fracDigits))
	scaledInt := scaled.IntPart()
	powFrac := pow10int64(fracDigits)
	powInt := pow10int64(intPlaceCount)
	var fracInt int64
	var intInt int64
	if powFrac != 0 {
		fracInt = scaledInt % powFrac
		intInt = scaledInt / powFrac
	} else {
		fracInt = 0
		intInt = scaledInt
	}
	if powInt != 0 {
		intInt = intInt % powInt
	}
	intStr := fmt.Sprintf("%0*d", intPlaceCount, intInt)
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracInt)
	}
	res := make([]byte, len(pic))
	intIdx := 0
	fracIdx := 0
	significant := false
	for i := 0; i < len(pic); i++ {
		ch := pic[i]
		if dotIdx != -1 && i == dotIdx {
			res[i] = '.'
			continue
		}
		isIntSide := dotIdx == -1 || i < dotIdx
		if isIntSide {
			if ch == ',' {
				if significant {
					res[i] = ','
				} else {
					res[i] = ' '
				}
			} else if ch == 'Z' || ch == 'z' {
				d := intStr[intIdx]
				intIdx++
				if d != '0' {
					significant = true
					res[i] = d
				} else {
					if significant {
						res[i] = '0'
					} else {
						res[i] = ' '
					}
				}
			} else if ch == '9' {
				d := intStr[intIdx]
				intIdx++
				if d != '0' {
					significant = true
				}
				res[i] = d
			} else {
				res[i] = ch
			}
		} else {
			if ch == '9' || ch == 'Z' || ch == 'z' {
				d := fracStr[fracIdx]
				fracIdx++
				res[i] = d
			} else if ch == ',' {
				res[i] = ','
			} else {
				res[i] = ch
			}
		}
	}
	return string(res)
}

func parsePrincipal(s string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return decimal.New(n, -2)
}

func parseRate(s string) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return decimal.New(n, -2)
}

func parseYears(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return n
}

func parseLoanLine(line string) LoanRec {
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	var r LoanRec
	r.LrAcct = line[0:6]
	r.LrPrincipal = parsePrincipal(line[6:15])
	r.LrRate = parseRate(line[15:19])
	r.LrYears = parseYears(line[19:21])
	return r
}

func MAIN_PARA() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	loanScanner = bufio.NewScanner(loanFile)
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	loanFile.Close()
	SUMMARY_PARA()
}

func READ_PARA() {
	if loanScanner.Scan() {
		line := loanScanner.Text()
		LoanRecData = parseLoanLine(line)
	} else {
		if err := loanScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	prod := LoanRecData.LrPrincipal.Mul(LoanRecData.LrRate).Mul(decimal.NewFromInt(LoanRecData.LrYears))
	shifted := prod.Shift(-2)
	rounded := shifted.Round(2)
	WsInterest = fitDecimal(rounded, 9, 2)
	sum := WsTotal.Add(WsInterest).Truncate(2)
	WsTotal = fitDecimal(sum, 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(LoanRecData.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	os.Stdout.WriteString(LoanRecData.LrAcct + " " + WsPrinEd + " " + WsIntEd + "\n")
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	os.Stdout.WriteString("RECORDS: " + countStr + "\n")
	os.Stdout.WriteString("TOTAL INTEREST: " + WsTotalEd + "\n")
}

func main() {
	MAIN_PARA()
}
